mapper.select:
select model_name
from t_experiment_progress
where is_deleted =0
  and set_id = #{setId}
  and user_id = #{userId}
  and groups_id = #{groupsId}
  and experiment_id = #{experimentId}
  and model_name is not null
group by model_name

select c.username, b.id materialId, b.material_name, a.model_name data from t_experiment_progress a left join t_material b on a.material_id = b.id and b.is_delete = 0 left join sys_user c on a.user_id = c.id and c.is_deleted = 0 where a.is_deleted = 0 and a.groups_id = #{groupId} and a.element_id in
#{elementId}
order by a.user_id, a.sequence;
